import { test, expect } from '@playwright/test';

test.describe('File Upload Success Checkmark', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/upload'); // Replace with the actual URL
  });

  test('should display success checkmark after file upload', async ({ page }) => {
    const filePath = 'path/to/your/file.txt'; // Replace with the actual file path
    await page.getByLabel('Upload File').setInputFiles(filePath);
    await page.getByRole('button', { name: 'Upload' }).click();

    // Wait for the success checkmark to appear
    const checkmark = page.getByRole('img', { name: 'Success Checkmark' });
    await expect(checkmark).toBeVisible();
  });

  test('should not display success checkmark if upload fails', async ({ page }) => {
    const invalidFilePath = 'path/to/your/invalidfile.txt'; // Replace with an invalid file path
    await page.getByLabel('Upload File').setInputFiles(invalidFilePath);
    await page.getByRole('button', { name: 'Upload' }).click();

    // Check that the success checkmark is not visible
    const checkmark = page.getByRole('img', { name: 'Success Checkmark' });
    await expect(checkmark).not.toBeVisible();
  });
});
